{
  "command": "cat scripts/plot_prior_kl.py; git log --oneline -3 -- scripts/plot_prior_kl.py; grep -rn \"plot_prior_kl\\|prior_kl\" --include=*.md --include=*.html --include=*.py --include=*.json . | grep -v \"^./scripts/plot_prior_kl.py\" | head -20",
  "description": "Show the KL plot script and where it is used"
}

{
  "command": "cat wiki/analyses/m1-210210-reference/kl-M1_210210.csv; grep -rn -i \"kl-M1_210210\\|bar\" wiki/analyses/m1-210210-reference/*.html wiki/analyses/m1-210210-reference/*.md 2>/dev/null | grep -i \"kl\\|bar\" | head; ls results/dr2-quiescent-new-defaults/210210-M1_210210 results/m1-210210-reference/tau-1/poly10/210210-M1_210210 2>&1 | head; ls ceridwen/.venv/bin/python",
  "description": "Check KL table, wiki mentions and input data"
}

{
  "command": "ls wiki/analyses/m1-210210-reference/; grep -rln \"kl-M1_210210\" wiki | head; grep -rn -i \"bar\" $(grep -rln \"kl-M1_210210\" wiki) | head",
  "description": "Find wiki pages that embed the KL figure"
}

{
  "command": "sed -n 40,100p wiki/research/experiments/e-m1-210210-reference.md; grep -n -i \"kl\" wiki/notes/m1-210210-reference.md | head -20; grep -rln \"kl_table\" --include=*.ipynb --include=*.py . 2>/dev/null | grep -v \"^./results\" | head",
  "description": "Read research record and note around the KL figure"
}

{
  "command": "git log --all --oneline -- scripts/plot_prior_kl.py | head -20; echo ---; git log --all --oneline -S \"noise_floor\" -- scripts/plot_prior_kl.py | head; echo ---; git branch -a --contains d4bc517 | head",
  "description": "Check history of the KL plot script across branches"
}

{
  "command": "for c in cd75b91 f564360 232aab1 b0c2ca4; do echo \"=== $c\"; git show $c -- scripts/plot_prior_kl.py | grep -E \"^[-+].*(barh|errorbar|axvspan|axvline|xscale|floor|fmt=)\" ; done",
  "description": "Look for points, floor band and log axis in past script versions"
}

{
  "command": "python3 - <<'EOF'
import json
nb = json.load(open("notebooks/ceridwen_integrated_photometry_spectra.ipynb"))
for c in nb["cells"]:
    s = "".join(c["source"])
    if "kl_table" in s or "marginal_kl" in s:
        print(c["cell_type"], "-----\n", s, "\n")
EOF",
  "description": "Print the notebook's KL plotting cell"
}

{
  "command": "git diff ceridwen; git -C ceridwen status --short | head; find . -path ./ceridwen/.venv -prune -o -name \"ceridwen_result.h5\" -path \"*M1_210210*\" -print 2>/dev/null | head; git check-ignore -v results/dr2-quiescent-new-defaults/210210-M1_210210/ceridwen_result.h5",
  "description": "Check submodule state and search for fit A result file"
}

{
  "command": "ls -la results/dr2-quiescent-new-defaults/ | head; ls results/dr2-quiescent-new-defaults | wc -l; ls results/dr2-quiescent-new-defaults/*/ceridwen_result.h5 2>/dev/null | wc -l; grep -rn \"dr2-quiescent-new-defaults\" wiki/log.md | tail -3",
  "description": "Check what the fit A results folder holds"
}

{
  "command": "git log --oneline -3 -- wiki/analyses/m1-210210-reference/kl-M1_210210.csv wiki/analyses/m1-210210-reference/kl-M1_210210.png; git log --oneline -1 --format=\"%h %ad\" --date=iso -- scripts/plot_prior_kl.py; git show --stat d4bc517 | head -12",
  "description": "Compare KL table and script commit history"
}

{
  "command": "ls -la \"$TMPDIR/kl-preview.png\" && ceridwen/.venv/bin/python -c \"\nimport sys; from PIL import Image\nim = Image.open(sys.argv[1]); print(im.size); im.resize((900, round(im.size[1]*900/im.size[0])), Image.LANCZOS).save(sys.argv[2])\" \"$TMPDIR/kl-preview.png\" \"$TMPDIR/kl-preview-900.png\"",
  "description": "Resize preview to 900 px wide with PIL"
}

